const response = $input.first().json;
const positions = response.positions || response.targets || response || [];

if (!Array.isArray(positions) || positions.length === 0) {
  return [{ json: { _sql: "SELECT 0 AS inseridos;", totalRecords: 0 } }];
}

const esc = (v) => v != null ? String(v).replace(/'/g, "''") : null;
const valStr = (v) => v != null ? `'${esc(v)}'` : 'NULL';
const valNum = (v) => (v != null && !isNaN(v)) ? Number(v) : 'NULL';
const valBool = (v) => typeof v === 'boolean' ? (v ? 'TRUE' : 'FALSE') : 'NULL';
const valJson = (obj) => `'${JSON.stringify(obj).replace(/'/g, "''")}'::jsonb`;

const sqlStatements = [];
sqlStatements.push(`
CREATE SCHEMA IF NOT EXISTS bronze;
CREATE TABLE IF NOT EXISTS bronze.nuxeo_veiculos_posicao (
    id BIGSERIAL PRIMARY KEY,
    placa VARCHAR(20),
    complemento TEXT,
    device_id INT,
    icon INT,
    serial VARCHAR(50),
    endereco TEXT,
    cidade VARCHAR(150),
    estado VARCHAR(50),
    pais VARCHAR(50),
    latitude NUMERIC(10,6),
    longitude NUMERIC(10,6),
    data_gps TEXT,
    ignicao BOOLEAN,
    bloqueio BOOLEAN,
    panico BOOLEAN,
    velocidade NUMERIC(6,2),
    bateria BOOLEAN,
    antifurto TEXT,
    payload_json JSONB,
    ingested_at TIMESTAMPTZ DEFAULT NOW()
);

-- Self-healing: adiciona colunas caso a tabela ja existisse de criacoes anteriores
ALTER TABLE bronze.nuxeo_veiculos_posicao ADD COLUMN IF NOT EXISTS complemento TEXT;
ALTER TABLE bronze.nuxeo_veiculos_posicao ADD COLUMN IF NOT EXISTS device_id INT;
ALTER TABLE bronze.nuxeo_veiculos_posicao ADD COLUMN IF NOT EXISTS icon INT;
ALTER TABLE bronze.nuxeo_veiculos_posicao ADD COLUMN IF NOT EXISTS serial VARCHAR(50);
ALTER TABLE bronze.nuxeo_veiculos_posicao ADD COLUMN IF NOT EXISTS endereco TEXT;
ALTER TABLE bronze.nuxeo_veiculos_posicao ADD COLUMN IF NOT EXISTS cidade VARCHAR(150);
ALTER TABLE bronze.nuxeo_veiculos_posicao ADD COLUMN IF NOT EXISTS estado VARCHAR(50);
ALTER TABLE bronze.nuxeo_veiculos_posicao ADD COLUMN IF NOT EXISTS pais VARCHAR(50);
ALTER TABLE bronze.nuxeo_veiculos_posicao ADD COLUMN IF NOT EXISTS latitude NUMERIC(10,6);
ALTER TABLE bronze.nuxeo_veiculos_posicao ADD COLUMN IF NOT EXISTS longitude NUMERIC(10,6);
ALTER TABLE bronze.nuxeo_veiculos_posicao ADD COLUMN IF NOT EXISTS data_gps TEXT;
ALTER TABLE bronze.nuxeo_veiculos_posicao ADD COLUMN IF NOT EXISTS ignicao BOOLEAN;
ALTER TABLE bronze.nuxeo_veiculos_posicao ADD COLUMN IF NOT EXISTS bloqueio BOOLEAN;
ALTER TABLE bronze.nuxeo_veiculos_posicao ADD COLUMN IF NOT EXISTS panico BOOLEAN;
ALTER TABLE bronze.nuxeo_veiculos_posicao ADD COLUMN IF NOT EXISTS velocidade NUMERIC(6,2);
ALTER TABLE bronze.nuxeo_veiculos_posicao ADD COLUMN IF NOT EXISTS bateria BOOLEAN;
ALTER TABLE bronze.nuxeo_veiculos_posicao ADD COLUMN IF NOT EXISTS antifurto TEXT;
ALTER TABLE bronze.nuxeo_veiculos_posicao ADD COLUMN IF NOT EXISTS payload_json JSONB;
ALTER TABLE bronze.nuxeo_veiculos_posicao ADD COLUMN IF NOT EXISTS ingested_at TIMESTAMPTZ DEFAULT NOW();
`);

let totalRecords = 0;
const chunkSize = 500;

for (let i = 0; i < positions.length; i += chunkSize) {
  const chunk = positions.slice(i, i + chunkSize);
  const values = chunk.map(pos => {
    totalRecords++;
    return '('
      + valStr(pos.identifier) + ', '
      + valStr(pos.complement) + ', '
      + valNum(pos.deviceId) + ', '
      + valNum(pos.icon) + ', '
      + valStr(pos.serial) + ', '
      + valStr(pos.address) + ', '
      + valStr(pos.city) + ', '
      + valStr(pos.state) + ', '
      + valStr(pos.country) + ', '
      + valNum(pos.latitude) + ', '
      + valNum(pos.longitude) + ', '
      + valStr(pos.dateGps) + ', '
      + valBool(pos.ignition) + ', '
      + valBool(pos.block) + ', '
      + valBool(pos.panic) + ', '
      + valNum(pos.speed) + ', '
      + valBool(pos.baterry) + ', '
      + valStr(pos.antiTheft) + ', '
      + valJson(pos)
      + ')';
  }).join(',\n');

  sqlStatements.push(`
    INSERT INTO bronze.nuxeo_veiculos_posicao (
      placa, complemento, device_id, icon, serial, endereco, cidade, estado, pais,
      latitude, longitude, data_gps, ignicao, bloqueio, panico, velocidade, bateria, antifurto, payload_json
    ) VALUES ${values};
  `);
}

return [{ json: { _sql: sqlStatements.join('\n'), totalRecords } }];
